// Comparison of the calculator with NIST-equivalent IAPWS-95 (CoolProp HEOS::Water)
// and CoolProp IF97::Water at named reference states.
//   node scripts/reference-comparison.mjs          # rewrite docs + help table
//   node scripts/reference-comparison.mjs --check  # fail if they are out of date
// Reference values: tests/fixtures/reference-nist-coolprop.json, regenerated by
// scripts/reference-nist-coolprop.py (CoolProp is an external oracle only).
import fs from 'node:fs';
import {fileURLToPath} from 'node:url';
import {initialize,calculate} from '../src/engine.js';
import {metastableVapor} from '../src/metastable-vapor.js';

const root=new URL('../',import.meta.url);
export const PROPERTIES=['v','h','s','u','cp','cv','w','mu','lambda'];
export const LABELS={v:'v',h:'h',s:'s',u:'u',cp:'cp',cv:'cv',w:'w',mu:'μ',lambda:'λ'};
export const GROUPS={
 liquid:{uk:'Стиснена рідина (обл. 1)',en:'Compressed liquid (region 1)'},
 'high-pressure':{uk:'Рідина 100 МПа (обл. 1)',en:'Liquid at 100 MPa (region 1)'},
 saturation:{uk:'Лінія насичення x = 0 / 1 (обл. 4)',en:'Saturation line x = 0 / 1 (region 4)'},
 vapor:{uk:'Перегріта пара (обл. 2)',en:'Superheated steam (region 2)'},
 'near-critical':{uk:'Біля критичної точки (обл. 3)',en:'Near-critical (region 3)'},
 supercritical:{uk:'Надкритичний флюїд (обл. 2)',en:'Supercritical fluid (region 2)'},
 'high-temperature':{uk:'1500–1900 K (обл. 5)',en:'1500–1900 K (region 5)'},
 metastable:{uk:'Метастабільна пара',en:'Metastable vapor'}
};
// Acceptance limits (relative). Implementation checks compare the same formulation
// and must agree to rounding level; the formulation check (IF97 vs IAPWS-95) is
// limited by IF97's own fit to IAPWS-95 and is reported, with a loose guard only.
export const LIMITS={heos:1e-7,if97:2e-5,formulation:0.02,transport:1e-6};

const rel=(ours,ref)=>ours==null||ref==null||!Number.isFinite(ours)||!Number.isFinite(ref)?null:Math.abs(ours-ref)/Math.max(Math.abs(ref),1e-12);

function ours(row,model){
 if(row.group==='metastable')return model==='IF97'?metastableVapor(row.a,row.b):null;
 if(model==='IAPWS-95'&&row.b>1273&&row.mode==='pt')return null;
 if(row.mode==='px'){const s=calculate('satp',row.a,undefined,model).saturation;return {...(row.b?s.vapor:s.liquid),T:s.T};}
 return calculate(row.mode,row.a,row.b,model).state;
}

function deviations(state,ref){
 const out={};if(!state||!ref)return null;
 for(const k of PROPERTIES){const d=rel(state[k],ref[k]);if(d!=null)out[k]=d;}
 if(ref.T!=null&&state.T!=null)out.T=Math.abs(state.T-ref.T);
 return out;
}

export async function buildComparison(){
 await initialize(fs.readFileSync(new URL('vendor/seuif97_bg.wasm',root)));
 const fixture=JSON.parse(fs.readFileSync(new URL('tests/fixtures/reference-nist-coolprop.json',root),'utf8'));
 const states=fixture.states.map(row=>{
  const if97=ours(row,'IF97'),iapws95=ours(row,'IAPWS-95');
  return {id:row.id,group:row.group,mode:row.mode,a:row.a,b:row.b,
   values:{ours95:pick(iapws95),oursIF97:pick(if97),heos:row.heos,coolpropIF97:row.if97||null},
   heos:deviations(iapws95,row.heos),        // our IAPWS-95 vs CoolProp IAPWS-95 (NIST equation)
   if97:deviations(if97,row.if97),           // our IF97 vs CoolProp IF97
   formulation:deviations(if97,row.heos)};   // our IF97 vs IAPWS-95 (NIST equation)
 });
 const summary={};
 for(const kind of ['heos','if97','formulation']){summary[kind]={};
  for(const group of Object.keys(GROUPS)){const g={};
   for(const s of states.filter(s=>s.group===group&&s[kind]))for(const [k,d] of Object.entries(s[kind]))if(!g[k]||d>g[k].d)g[k]={d,id:s.id};
   if(Object.keys(g).length)summary[kind][group]=g;}}
 return {source:fixture.source,limits:LIMITS,states,summary};
}
function pick(q){if(!q)return null;const o={};for(const k of ['T',...PROPERTIES])if(q[k]!=null)o[k]=q[k];return o;}

// CoolProp IF97 takes saturation states above 623.15 K (p > 16.529 MPa) from the
// region-3 backward equations; this calculator iterates them to the basic equation.
export const backwardSaturation=s=>s.mode==='px'&&s.a>16.529;
export function violations(result){
 const out=[];
 for(const s of result.states)for(const kind of ['heos','if97','formulation']){const d=s[kind];if(!d)continue;
  // Region 5 lies beyond IAPWS-95's 1273 K limit: reported, not gated.
  if(kind==='formulation'&&s.group==='high-temperature')continue;
  for(const [k,value] of Object.entries(d)){
   let limit;
   if(kind==='heos')limit=k==='T'?1e-6:['mu','lambda'].includes(k)?LIMITS.transport:LIMITS.heos;
   else if(kind==='if97')limit=backwardSaturation(s)?1e-2:k==='T'?1e-6:['mu','lambda'].includes(k)?2e-3:LIMITS.if97;
   // Formulation guard on v, h, s, u and Tsat only: derivative properties (cp, cv, w) and μ, λ diverge near the critical point.
   else if(['v','h','s','u'].includes(k))limit=LIMITS.formulation;else if(k==='T')limit=0.05;else continue;
   if(value>limit)out.push(`${s.id} ${kind} ${k}: ${value.toExponential(3)} > ${limit}`);}}
 return out;
}

// ---------- presentation ----------
const fmt=d=>{if(d==null)return '—';if(d===0)return '0';if(d<1e-12)return '&lt; 10<sup>−12</sup>';const [m,e]=d.toExponential(1).split('e');return `${m}·10<sup>${e.replace('-','−').replace('+','')}</sup>`;};
const pct=d=>d==null?'—':(d*100<0.0001?'<0.0001':(d*100).toPrecision(2))+'%';
const KEYS_TABLE=['v','h','s','cp','w'];

function groupRows(result,kind,format){
 return Object.keys(GROUPS).filter(g=>result.summary[kind][g]).map(g=>[g,KEYS_TABLE.map(k=>format(result.summary[kind][g][k]?.d))]);
}

export function helpHtml(result){
 const head='<tr><th>Область</th>'+KEYS_TABLE.map(k=>`<th>${LABELS[k]}</th>`).join('')+'</tr>';
 const table=(kind,format)=>'<table class="reference-comparison"><thead>'+head+'</thead><tbody>'+groupRows(result,kind,format).map(([g,cells])=>`<tr><td>${GROUPS[g].uk}</td>${cells.map(c=>`<td>${c.replace(/^<(\d)/,'&lt;$1')}</td>`).join('')}</tr>`).join('')+'</tbody></table>';
 return ['<!-- reference-comparison:start (generated by scripts/reference-comparison.mjs) -->',
  '<details id="reference-comparison"><summary>Звірка з NIST і CoolProp</summary>',
  '<p>NIST REFPROP і NIST Chemistry WebBook розраховують воду за IAPWS-95. Таку саму формуляцію реалізує CoolProp HEOS. Нижче наведено найбільші відносні відхилення наших результатів у контрольних станах за областями.</p>',
  '<h3>IAPWS-95 цього калькулятора порівняно з NIST IAPWS-95 (CoolProp HEOS)</h3>',
  '<p>Однакова формуляція: відхилення відображає лише похибку обчислень.</p>',
  table('heos',fmt),
  '<h3>IF97 цього калькулятора порівняно з IAPWS-95 (NIST)</h3>',
  '<p>Різниця формуляцій: IF97 — промислове наближення IAPWS-95. Ці числа показують, наскільки результат IF97 відрізняється від наукового еталона. Для точних наукових розрахунків оберіть формуляцію IAPWS-95.</p>',
  table('formulation',pct),
  '<p>IF97 цього калькулятора порівняно з CoolProp IF97: найбільше відхилення <b>'+fmt(maxOf(result,'if97',['v','h','s','cp','w'],s=>!backwardSaturation(s)))+'</b>. Виняток — насичення вище 623,15 K, де CoolProp бере густину зі зворотних рівнянь області 3: до <b>'+fmt(maxOf(result,'if97',['v','h','s','cp','w'],backwardSaturation))+'</b>.</p>',
  '<p>Повна таблиця станів, μ, λ і методика: docs/REFERENCE_COMPARISON.md у репозиторії.</p>',
  '</details>','<!-- reference-comparison:end -->'].join('');
}
function maxOf(result,kind,keys,filter=()=>true){let m=0;for(const s of result.states)if(s[kind]&&filter(s))for(const k of keys)if(s[kind][k]>m)m=s[kind][k];return m;}

const sci=d=>d==null?'—':d===0?'0':d.toExponential(1);
function mdTable(result,kind,format,lang){
 const keys=['v','h','s','u','cp','cv','w','mu','lambda'];
 const lines=[`| ${lang==='uk'?'Область':'Region'} | ${keys.map(k=>LABELS[k]).join(' | ')} |`,`|---|${keys.map(()=>'---:').join('|')}|`];
 for(const g of Object.keys(GROUPS))if(result.summary[kind][g])lines.push(`| ${GROUPS[g][lang]} | ${keys.map(k=>format(result.summary[kind][g][k]?.d)).join(' | ')} |`);
 return lines.join('\n');
}
function stateTable(result,lang){
 const keys=['v','h','s','cp','w'];
 const lines=[`| ${lang==='uk'?'Стан':'State'} | p, MPa | ${lang==='uk'?'T, K / x':'T, K / x'} | ${keys.map(k=>'Δ'+LABELS[k]+' 95').join(' | ')} | ${keys.map(k=>'Δ'+LABELS[k]+' IF97').join(' | ')} |`,`|---|---:|---:|${keys.map(()=>'---:').join('|')}|${keys.map(()=>'---:').join('|')}|`];
 for(const s of result.states)lines.push(`| ${s.id} | ${s.a} | ${s.mode==='px'?'x = '+s.b:s.b} | ${keys.map(k=>sci(s.heos?.[k])).join(' | ')} | ${keys.map(k=>pct(s.formulation?.[k])).join(' | ')} |`);
 return lines.join('\n');
}

export function markdown(result){
 return `# Звірка з NIST і CoolProp / Comparison with NIST and CoolProp

_Згенеровано \`node scripts/reference-comparison.mjs\`. Не редагуйте вручну._
_Generated by \`node scripts/reference-comparison.mjs\`. Do not edit by hand._

Еталон / reference: ${result.source}.

## Українською

**Що з чим порівнюється.** NIST REFPROP 10 і NIST Chemistry WebBook розраховують властивості води за IAPWS-95 (Wagner, Pruß, J. Phys. Chem. Ref. Data 31 (2002) 387). CoolProp HEOS::Water реалізує те саме рівняння, тому його значення використано як NIST-еквівалентний еталон. Прямий запит до WebBook із хмарного середовища збірки заблоковано мережею; див. розділ «Обмеження».

Порівняно ${result.states.length} контрольних станів у восьми групах: стиснена рідина, рідина 100 МПа, лінія насичення (x = 0 і 1), перегріта пара, біля критичної точки (область 3), надкритичний флюїд, 1500–1900 K (область 5), метастабільна пара. Усі числа — відносні відхилення |наше − еталон| / |еталон|.

Три перевірки:

1. **IAPWS-95 калькулятора проти NIST IAPWS-95 (CoolProp HEOS).** Однакова формуляція, тому відхилення показує лише якість реалізації. Допуск ${LIMITS.heos}; для μ і λ ${LIMITS.transport}.
2. **IF97 калькулятора проти IF97 CoolProp.** Однакова формуляція. Допуск ${LIMITS.if97}. Виняток — лінія насичення вище 623,15 K (20 і 21,5 МПа): CoolProp бере там густину фаз зі зворотних рівнянь області 3 (IAPWS SR5-05), а калькулятор уточнює її до кореня основного рівняння. Це уточнення окремо підтверджено Python iapws (docs/INDEPENDENT_VALIDATION.md); для цих станів допуск 10⁻².
3. **IF97 калькулятора проти IAPWS-95 (NIST).** Різниця формуляцій, а не похибка коду: IF97 — промислове наближення IAPWS-95. Таблиця показує, яку похибку відносно наукового еталона має користувач, що обирає IF97. Контрольна межа ${LIMITS.formulation * 100}% для v, h, s, u (крім області 5, де IAPWS-95 екстрапольовано за 1273 K). Похідні властивості cp, cv, w, а також μ і λ біля критичної точки змінюються дуже різко, тому їх наведено без межі. Відносне відхилення h, s, u у рідині біля 0 °C завищене, бо самі значення близькі до нуля.

### 1. IAPWS-95 калькулятора проти NIST IAPWS-95, найбільше відносне відхилення

${mdTable(result,'heos',sci,'uk')}

### 2. IF97 калькулятора проти CoolProp IF97

${mdTable(result,'if97',sci,'uk')}

### 3. IF97 калькулятора проти IAPWS-95 (NIST), %

${mdTable(result,'formulation',pct,'uk')}

Метастабільна пара: IF97 — додаткове рівняння R7-97 §6.2.3; еталон — паровий корінь IAPWS-95 нижче температури насичення (CoolProp HEOS з примусовою газовою фазою). Метастабільний стан IAPWS-95 калькулятор не розраховує, тому перевірка 1 там відсутня. Велика різниця cp і cv (до 15%) показує невизначеність екстраполяції обох рівнянь у метастабільну область, а не помилку.

### Обмеження

- Прямий доступ до webbook.nist.gov із середовища збірки заборонено мережевою політикою. Порівняння з NIST спирається на те, що NIST використовує IAPWS-95, а офіційні контрольні значення IAPWS-95 (R6-95(2018), табл. 6–8) перевірено окремо в tests/official.test.mjs.
- Область 5 (1500–1900 K) лежить за межею IAPWS-95 (1273 K); CoolProp екстраполює рівняння, тому розбіжність там не є похибкою IF97.
- μ і λ вище 1173,15 K калькулятор не наводить (межі IAPWS 2008/2011).
- Порівняння не замінює сертифікацію IAPWS.

### Як повторити

\`\`\`
pip install CoolProp==8.0.0
python scripts/reference-nist-coolprop.py      # оновити еталонні значення
node scripts/reference-comparison.mjs          # таблиці в docs і в «Довідці»
node --test tests/reference-comparison.test.mjs
\`\`\`

## English

**What is compared.** NIST REFPROP 10 and the NIST Chemistry WebBook compute water properties with IAPWS-95 (Wagner & Pruß 2002). CoolProp HEOS::Water implements the same equation, so it serves as the NIST-equivalent reference. ${result.states.length} named states in eight groups; all numbers are relative deviations |ours − reference| / |reference|.

1. **Our IAPWS-95 vs NIST IAPWS-95 (CoolProp HEOS):** same formulation; the deviation measures implementation quality only. Limit ${LIMITS.heos} (μ, λ: ${LIMITS.transport}).
2. **Our IF97 vs CoolProp IF97:** same formulation, limit ${LIMITS.if97}. Exception: saturation above 623.15 K (20 and 21.5 MPa), where CoolProp takes phase densities from the region-3 backward equations (IAPWS SR5-05) while this calculator iterates to the root of the basic equation (confirmed separately with Python iapws); limit 10⁻² there.
3. **Our IF97 vs IAPWS-95 (NIST):** a formulation difference, not a code error. It is the error a user accepts by choosing the industrial IF97. Guard ${LIMITS.formulation * 100}% on v, h, s, u (region 5 excluded: IAPWS-95 is extrapolated above 1273 K). Derivative properties cp, cv, w and μ, λ vary steeply near the critical point and are reported without a limit. Relative h, s, u deviations of liquid near 0 °C are inflated because the values themselves are close to zero.

### 1. Our IAPWS-95 vs NIST IAPWS-95, maximum relative deviation

${mdTable(result,'heos',sci,'en')}

### 2. Our IF97 vs CoolProp IF97

${mdTable(result,'if97',sci,'en')}

### 3. Our IF97 vs IAPWS-95 (NIST), %

${mdTable(result,'formulation',pct,'en')}

Limitations: webbook.nist.gov is not reachable from the build environment; the IAPWS-95 check values of R6-95(2018) are verified separately in tests/official.test.mjs. Region 5 lies beyond IAPWS-95's 1273 K limit. Not an IAPWS certification.

## Усі стани / All states

Δ… 95 — IAPWS-95 калькулятора проти NIST IAPWS-95 (відносне); Δ… IF97 — IF97 калькулятора проти IAPWS-95, %. Повні значення: docs/reference-comparison-results.json.

${stateTable(result,'uk')}
`;
}

export function writeOutputs(result,check=false){
 const files=[[new URL('docs/REFERENCE_COMPARISON.md',root),markdown(result)],[new URL('docs/reference-comparison-results.json',root),JSON.stringify(result,null,1)+'\n']];
 const templateUrl=new URL('src/template.html',root),template=fs.readFileSync(templateUrl,'utf8');
 const block=/<!-- reference-comparison:start[\s\S]*?<!-- reference-comparison:end -->/;
 const html=helpHtml(result);
 const next=block.test(template)?template.replace(block,html):template.replace('<details><summary>Джерела, ліцензії та числова точність</summary>',html+'<details><summary>Джерела, ліцензії та числова точність</summary>');
 files.push([templateUrl,next]);
 const stale=[];
 for(const [url,content] of files){const old=fs.existsSync(url)?fs.readFileSync(url,'utf8'):'';const cmp=s=>url.pathname.endsWith('.md')?s.replace(/^_.*_$/mg,''):s;if(cmp(old)!==cmp(content)){stale.push(fileURLToPath(url));if(!check)fs.writeFileSync(url,content);}}
 return stale;
}

if(process.argv[1]===fileURLToPath(import.meta.url)){
 const result=await buildComparison(),check=process.argv.includes('--check');
 const stale=writeOutputs(result,check),bad=violations(result);
 for(const kind of ['heos','if97','formulation'])console.log(kind,maxOf(result,kind,['v','h','s','cp','w']).toExponential(2));
 if(bad.length){console.error(bad.join('\n'));process.exitCode=1;}
 if(check&&stale.length){console.error('Out of date:',stale.join(', '));process.exitCode=1;}
}
